import express, { Express, Request, Response } from 'express';
import { OrderService } from '../application/OrderService';
import { CatalogueService } from '../application/CatalogueService';
import { Catalogue } from '../domain/Catalogue';

export function createApp(): Express {
  const app = express();
  app.use(express.json());

  // Initialize services
  const catalogue = new Catalogue();
  const orderService = new OrderService(catalogue);
  const catalogueService = new CatalogueService(catalogue);

  // Initialize sample data
  catalogueService.addProduct('PROD001', 'Laptop', 999.99, 5);
  catalogueService.addProduct('PROD002', 'Mouse', 29.99, 50);
  catalogueService.addProduct('PROD003', 'Keyboard', 79.99, 30);

  // Product endpoints
  app.get('/products', (_req: Request, res: Response<any>) => {
    const products = catalogueService.getAllProductsWithStock();
    res.json(products);
  });

  app.get('/products/:productId', (req: Request, res: Response<any>) => {
    const productId = String(req.params.productId);
    const product = catalogueService.getProductWithStock(productId);
    if (!product) {
      return res.status(404).json({ error: 'Product not found' });
    }
    res.json(product);
  });

  // Order endpoints
  app.post('/orders', (req: Request, res: Response<any>) => {
    try {
      const { items } = req.body;
      if (!Array.isArray(items) || items.length === 0) {
        return res.status(400).json({ error: 'Items array is required and must not be empty' });
      }

      const order = orderService.createOrder(items);
      res.status(201).json(order);
    } catch (error) {
      const message = error instanceof Error ? error.message : 'Unknown error';
      res.status(400).json({ error: message });
    }
  });

  app.get('/orders', (req: Request, res: Response<any>) => {
    const state = req.query.state as string | undefined;
    const orders = state ? orderService.getOrdersByState(state as any) : orderService.getAllOrders();
    res.json(orders);
  });

  app.get('/orders/:orderId', (req: Request, res: Response<any>) => {
    const orderId = String(req.params.orderId);
    const order = orderService.getOrder(orderId);
    if (!order) {
      return res.status(404).json({ error: 'Order not found' });
    }
    res.json(order);
  });

  app.patch('/orders/:orderId/state', (req: Request, res: Response<any>) => {
    try {
      const { state } = req.body;
      if (!state) {
        return res.status(400).json({ error: 'State is required' });
      }

      const orderId = String(req.params.orderId);
      const order = orderService.transitionOrder(orderId, state);
      res.json(order);
    } catch (error) {
      const message = error instanceof Error ? error.message : 'Unknown error';
      res.status(400).json({ error: message });
    }
  });

  app.post('/orders/:orderId/cancel', (req: Request, res: Response<any>) => {
    try {
      const orderId = String(req.params.orderId);
      const order = orderService.cancelOrder(orderId);
      res.json(order);
    } catch (error) {
      const message = error instanceof Error ? error.message : 'Unknown error';
      res.status(400).json({ error: message });
    }
  });

  return app;
}

